def isAnagram(s: str, t: str) -> bool:

    # implement your solution here.

    # if lengths differ, they can't be anagrams, so return false immediately
    if len(s) != len(t):
        return False

    # dictionary to count frequency of letters in s
    count = {}

    # counting chars in s
    for char in s:
        count[char] = count.get(char, 0) + 1

    # check each char in t against the dictionary
    for char in t:

        # if character doesn't exist in s, not an anagram, so return false
        if char not in count:
            return False

        count[char] -= 1

        # if count goes (-), t has more of this char than s, so not an anagram so return false
        if count[char] < 0:
            return False

    # otherwise, return true! they are anagrams yayyyy
    return True

