def isAnagram(s: str, t: str) -> bool:
    cs = {}
    # do a pass over s to accumulate character counts
    for c in s:
        if not cs[c]: cs[c] = 0
        cs[c] += 1

    # now do a second pass over t, draining the accumulated character counts
    for c in t:
        if not cs[c]: return False # it has a character that doesnt exist in the before string, not anagram, or it exists too many times in the current string
        cs[c] -= 1
        if cs[c] == 0: del cs[c]

    return len(cs) == 0 # if len is zero we perfectly drained all the characters without going over or under. if not then gg unlucky

